export function getHindiPage(slug: string): HindiPageArticle | undefined {
  return HINDI_PAGES.find((p) => p.slug === slug || p.urlPath === slug || p.urlPath === `/hi/${slug}` || p.urlPath === `/hi/guides/${slug}` || p.urlPath === `/hi/packages/from/${slug}`);
}
